package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.DocumentsContract;
/** System file picker grants access only to the file selected by the user. */
public final class UsbFilesActivity extends Activity {
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null)return;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(Build.VERSION.SDK_INT>=26){String volume=getIntent().getStringExtra("volume");if(volume!=null)pick.putExtra(DocumentsContract.EXTRA_INITIAL_URI,DocumentsContract.buildDocumentUri("com.android.externalstorage.documents",volume+":"));}try{openPicker(pick);}catch(ActivityNotFoundException e){try{Intent fallback=new Intent(Intent.ACTION_GET_CONTENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);openPicker(fallback);return;}catch(ActivityNotFoundException unavailable){}new AlertDialog.Builder(this).setTitle("USB").setMessage(UiSettings.text(this,"النظام لا يوفر متصفح ملفات للتطبيقات. افتح الفلاشة من مشغّل الوسائط أو مدير الملفات الخاص بالجهاز.","This TV has no system file picker. Open USB using the TV media player or an installed file manager.")).setPositiveButton(UiSettings.text(this,"إعدادات التخزين","Storage settings"),(d,w)->{try{startActivity(new Intent(android.provider.Settings.ACTION_INTERNAL_STORAGE_SETTINGS));}catch(RuntimeException ignored){}finish();}).setNegativeButton(UiSettings.text(this,"رجوع","Back"),(d,w)->finish()).setOnCancelListener(d->finish()).show();}}
 /** Resolve explicitly so a third-party TV resolver cannot place its chooser off-screen. */
 private void openPicker(Intent intent){
  java.util.List<android.content.pm.ResolveInfo> found=getPackageManager().queryIntentActivities(intent,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY),valid=new java.util.ArrayList<>();
  for(android.content.pm.ResolveInfo row:found){android.content.pm.ActivityInfo info=row.activityInfo;String label=String.valueOf(row.loadLabel(getPackageManager()));if(info==null||!info.exported||!info.enabled||(info.name.toLowerCase(java.util.Locale.ROOT).contains("stub")||info.name.toLowerCase(java.util.Locale.ROOT).contains("photopicker")&&"*/*".equals(intent.getType()))||"Activity Stub".equalsIgnoreCase(label))continue;if(info.packageName.endsWith(".documentsui")&&(info.applicationInfo.flags&android.content.pm.ApplicationInfo.FLAG_SYSTEM)!=0){startActivityForResult(new Intent(intent).setComponent(new ComponentName(info.packageName,info.name)),671);return;}valid.add(row);}
  if(valid.isEmpty())throw new ActivityNotFoundException("No document picker available");
  if(valid.size()==1){android.content.pm.ActivityInfo info=valid.get(0).activityInfo;startActivityForResult(new Intent(intent).setComponent(new ComponentName(info.packageName,info.name)),671);return;}
  String[] names=new String[valid.size()];for(int i=0;i<names.length;i++)names[i]=String.valueOf(valid.get(i).loadLabel(getPackageManager()));
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle(UiSettings.text(this,"اختيار الملفات","Choose files")).setItems(names,(d,index)->{android.content.pm.ActivityInfo info=valid.get(index).activityInfo;try{startActivityForResult(new Intent(intent).setComponent(new ComponentName(info.packageName,info.name)),671);}catch(RuntimeException error){finish();}}).setNegativeButton(UiSettings.text(this,"رجوع","Back"),(d,w)->finish()).setOnCancelListener(d->finish()).create();dialog.show();android.view.Window window=dialog.getWindow();if(window!=null){android.util.DisplayMetrics dm=getResources().getDisplayMetrics();window.setGravity(android.view.Gravity.CENTER);window.setLayout(Math.min((int)(dm.widthPixels*.8f),(int)(720*dm.density)),Math.min((int)(dm.heightPixels*.72f),(int)((120+valid.size()*56)*dm.density)));}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=671)return;if(result==RESULT_OK&&data!=null&&(data.getData()!=null||data.getClipData()!=null)){if(data.getClipData()!=null&&data.getClipData().getItemCount()>1){java.util.List<Uri> selected=new java.util.ArrayList<>();for(int i=0;i<data.getClipData().getItemCount()&&i<LocalMediaQueue.LIMIT;i++)selected.add(data.getClipData().getItemAt(i).getUri());try{org.json.JSONArray queue=LocalMediaQueue.selected(this,selected);if(queue.length()>0){Uri first=Uri.parse(queue.getJSONObject(0).getString("uri"));Intent player=new Intent(this,UsbPlayerActivity.class).setData(first).putExtra("queue",queue.toString()).putExtra("queueIndex",0).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);player.setClipData(LocalMediaQueue.grants(queue));startActivity(player);}else android.widget.Toast.makeText(this,UiSettings.text(this,"الاختيار لا يحتوي على فيديوهات.","The selection contains no videos."),1).show();}catch(Exception error){android.widget.Toast.makeText(this,UiSettings.text(this,"تعذّر فتح الملفات المختارة.","Could not open the selected files."),1).show();}finish();return;}Uri uri=data.getData()!=null?data.getData():data.getClipData().getItemAt(0).getUri();if(!"content".equals(uri.getScheme())){finish();return;}String name=uri.getLastPathSegment();try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}catch(RuntimeException ignored){}String type=UsbMediaTypes.resolve(getContentResolver().getType(uri),name);if(type==null){android.widget.Toast.makeText(this,UiSettings.text(this,"نوع الملف غير معروف كصورة أو صوت أو فيديو.","The selected file is not recognized as video, audio or an image."),1).show();finish();return;}if(type.startsWith("video/")){Intent local=new Intent(this,UsbPlayerActivity.class).setData(uri).putExtra("name",name).putExtra("mime",type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);local.setClipData(ClipData.newRawUri("USB video",uri));startActivity(local);finish();return;}try{Intent play=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);play.setClipData(ClipData.newRawUri("USB media",uri));startActivity(Intent.createChooser(play,UiSettings.text(this,"فتح ملف الفلاشة","Open USB media")));}catch(RuntimeException e){android.widget.Toast.makeText(this,UiSettings.text(this,"لا يوجد مشغّل مثبت يدعم الملف المختار.","No installed player supports the selected file."),1).show();}}finish();}
}
